import math
def priority(task, state, m=5.0, c=0.25, r=0.2, map_b=1.0, reduce_b=1.0, join_b=1.0, other_b=1.0):
    p = max(task.estimated_runtime, 1e-6)
    need = max(task.resource_need, 1e-6)
    w = max(task.weight, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'map':
        tb = map_b
    elif task.task_type == 'reduce':
        tb = reduce_b
    elif task.task_type == 'join':
        tb = join_b
    else:
        tb = other_b
    denom = max(p + c * max(state.mean_est, 1e-6), 1e-6)
    return tier * w * tb / (denom * (need ** r))

import math
def priority(task, state, m=5.0, alpha=1.0, b=0.5, g=1.0, k=2.0, d=0.1, map_b=1.0, reduce_b=1.0, join_b=1.0, other_b=1.0):
    p = max(task.estimated_runtime, 1e-6)
    w = max(task.weight, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'map':
        tb = map_b
    elif task.task_type == 'reduce':
        tb = reduce_b
    elif task.task_type == 'join':
        tb = join_b
    else:
        tb = other_b
    wait = max(0.0, state.now - task.release)
    mean = max(state.mean_est, 1e-6)
    scale = max(p + mean, 1e-6)
    age = (1.0 + b * wait / scale) ** g
    slack = max(0.0, task.due - state.now - p)
    urgency = 1.0 + d * math.exp(-slack / max(k * mean, 1e-6))
    return tier * w * tb * age * urgency / max(p ** alpha, 1e-6)

