import math
def priority(task, state, m=10.0, bm=1.0, br=1.0, bj=1.0, bo=1.0, beta=0.5):
    est = max(task.estimated_runtime, 1e-6)
    if task.task_type == 'map':
        typ = bm
    elif task.task_type == 'reduce':
        typ = br
    elif task.task_type == 'join':
        typ = bj
    else:
        typ = bo
    tier = m if task.tenant == 'premium' else 1.0
    pressure = state.queue_work / max(state.capacity * max(state.mean_est, 1e-6), 1e-6)
    if task.tenant == 'premium':
        tier *= max(1.0 + beta * pressure, 1e-6)
    return tier * typ / est

def priority(task, state, m=10.0, bm=1.0, br=1.0, bj=1.0, bo=1.0, a=0.2, b=1.0, beta=0.25, alpha=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'map':
        typ = bm
    elif task.task_type == 'reduce':
        typ = br
    elif task.task_type == 'join':
        typ = bj
    else:
        typ = bo
    wait = max(0.0, state.now - task.release)
    age = 1.0 + a * wait / max(wait + b * mean, 1e-6)
    r = max(task.resource_need, 1e-6)
    cap = max(state.capacity, 1e-6)
    pack = 1.0 / max(1.0 + beta * r / cap, 1e-6)
    return tier * typ * age * pack / (est ** alpha)

def priority(task, state, m=5.0, alpha=1.0, beta=0.25, gamma=0.5, wpow=0.0, bm=1.0, br=1.0, bj=1.0, bo=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, est, 1e-6)
    r = max(task.resource_need, 1e-6)
    cap = max(state.capacity, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    pressure = state.queue_work / max(cap * mean, 1e-6)
    if task.tenant == 'premium':
        tier *= 1.0 + gamma * pressure
    if task.task_type == 'map':
        typ = bm
    elif task.task_type == 'reduce':
        typ = br
    elif task.task_type == 'join':
        typ = bj
    else:
        typ = bo
    wt = max(task.weight, 1e-6) ** wpow
    pack = 1.0 / max(1.0 + beta * r / cap, 1e-6)
    return tier * typ * wt * pack / max(est ** alpha, 1e-6)

