import math
def priority(task, state, m=10.0, beta=0.05, p=0.0, a=0.05, map_mult=1.0, reduce_mult=1.0, join_mult=1.0, other_mult=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    weight = max(task.weight, 1e-6) ** p
    if task.task_type == 'map':
        typ = map_mult
    elif task.task_type == 'reduce':
        typ = reduce_mult
    elif task.task_type == 'join':
        typ = join_mult
    else:
        typ = other_mult
    eff = est + beta * mean
    wait = max(0.0, state.now - task.release)
    age = 1.0 + a * wait / max(eff + mean, 1e-6)
    return tier * weight * typ * age / max(eff, 1e-6)

import math
def priority(task, state, m=10.0, m1=5.0, q0=2.0, a=0.10, beta=0.05):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    if state.queue_len <= q0:
        tier = m if task.tenant == 'premium' else 1.0
        return tier / est
    load = state.queue_work / max(state.capacity * mean, 1e-6)
    if task.tenant == 'premium':
        tier = m + m1 * (1.0 - math.exp(-max(0.0, load)))
    else:
        tier = 1.0
    wait = max(0.0, state.now - task.release)
    age = 1.0 + a * wait / max(mean, 1e-6)
    eff = est + beta * mean
    return tier * age / max(eff, 1e-6)

