import math
def priority(task, state, m=5.0, p=1.0, w=1.0, b=1.0, a=0.0,
             tmap=1.0, tred=1.0, tjoin=1.0, tother=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    late = max(0.0, state.now + est - task.due)
    tier = m if task.tenant == 'premium' else 1.0
    wt = max(task.weight, 1e-6) ** w
    if task.task_type == 'map':
        tf = tmap
    elif task.task_type == 'reduce':
        tf = tred
    elif task.task_type == 'join':
        tf = tjoin
    else:
        tf = tother
    age = math.exp(min(20.0, max(-20.0, b * wait / mean)))
    due_boost = 1.0 + a * late / est
