import math
def priority(task, state, m=5.0, pm=1.0, ps=0.2, p=1.0, k=1.0, w=1.0, g=1.0,
             tmap=1.0, tred=1.0, tjoin=1.0, tother=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    slack = task.due - state.now - est
    if task.tenant == 'premium':
        tier = m + pm * wait / mean
    else:
        tier = 1.0 + ps * wait / mean
    if slack <= 0.0:
        urg = max(0.0, 1.0 + g * (-slack) / mean)
    else:
        urg = math.exp(-slack / max(k * mean, 1e-6))
    if task.task_type == 'map':
        tf = tmap
    elif task.task_type == 'reduce':
        tf = tred
    elif task.task_type == 'join':
        tf = tjoin
    else:
        tf = tother
    wt = max(task.weight, 1e-6) ** w
    return tier * tf * wt * urg / (est ** p)

