import math
def priority(task, state, m=5.0, b=0.8, alpha=0.9, k=2.0, g=1.5, cap=20.0, map_mul=1.0, reduce_mul=1.0, join_mul=1.1, other_mul=1.0):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    mean = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'map':
        type_mul = map_mul
    elif task.task_type == 'reduce':
        type_mul = reduce_mul
    elif task.task_type == 'join':
        type_mul = join_mul
    else:
        type_mul = other_mul
    age = 1.0 + b * (wait / mean) ** alpha
    slack = task.due - state.now - est
    x = -max(-50.0, min(50.0, slack / max(k * mean, 1e-6)))
    risk = 1.0 + g * math.exp(x)
    if risk > cap:
        risk = cap
    return tier * type_mul * task.weight * age * risk / max(est * (cores ** 0.05), 1e-6)

